import { getParentByClass } from "../getParentByClass";
export const isChildPopup = (target, popup) => {
    const parent = getParentByClass(target, "zen-absolute");
    if (!parent) {
        return false;
    }
    if (parent === popup) {
        return true;
    }
    const trigger = document.querySelector(`[data-popup-id='${parent.id}']`);
    if (!trigger) {
        return false;
    }
    return isChildPopup(trigger, popup);
};
